import sys
from collections import defaultdict, deque

def find_cycle(graph, start):
    visited = set()
    parent = {start: None}
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            cycle = []
            while node is not None:
                cycle.append(node)
                node = parent[node]
            return cycle[::-1]
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                parent[neighbor] = node
                stack.append(neighbor)
    return []

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    edges = [(int(input[2 + 2 * i]) - 1, int(input[3 + 2 * i]) - 1) for i in range(m)]

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    cycle = []
    for i in range(n):
        cycle = find_cycle(graph, i)
        if len(cycle) > 2:
            break

    if len(cycle) <= 2:
        print("NO")
        return

    if len(cycle) < 5:
        print("NO")
        return

    routes = [
        [cycle[0]] + cycle[2::-1] + [cycle[0]],
        [cycle[0]] + cycle[3:1:-1] + [cycle[0]],
        [cycle[0]] + [cycle[4]] + [cycle[0]]
    ]

    print("YES")
    for route in routes:
        print(len(route), *(x + 1 for x in route))

